def transform(grid):
    rows, cols = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r0 in range(rows - 4):
        for r1 in range(r0 + 4, rows):
            c = 0
            while c < cols:
                color = grid[r0][c]
                if all(grid[r][c] == color for r in range(r0, r1 + 1)):
                    start = c
                    c += 1
                    while c < cols and grid[r0][c] == color and all(grid[r][c] == color for r in range(r0, r1 + 1)):
                        c += 1
                    if c - start >= 5:
                        for r in range(r0, r1 + 1):
                            for j in range(start, c):
                                out[r][j] = 4
                else:
                    c += 1
    return out
